function plot_execution_allocation(root)
% Read actual recorded MuJoCo experiments. Never synthesize trajectories.
if nargin<1,root=fileparts(fileparts(mfilename('fullpath')));end
d=jsondecode(fileread(fullfile(root,'research','execution','figure_data.json')));out=fullfile(root,'assets','result');set(groot,'defaultFigureVisible','off');set(groot,'defaultAxesFontSize',10);
cols=[0 114 178;213 94 0;0 158 115;204 121 167;230 159 0;86 180 233;140 86 75;111 78 124;77 77 77]/255;method=[.07 .42 .59;.75 .32 .13;.47 .31 .65;.37 .48 .56];names={'Cyclic centroid','Cyclic repair','Order-k Voronoi','Feasible geometric'};r=d.replay;
f=figure('Color','w','Position',[20 20 1500 1000]);tiledlayout(2,2,'Padding','compact','TileSpacing','compact');
nexttile;plot(r.time,100*[r.cyclic r.voronoi r.repair],'LineWidth',1.6);hold on;plot(r.time,100*r.ceiling,'k--','LineWidth',1.1);grid on;ylim([0 45]);xlabel('Motion time (s)');ylabel('Simultaneous two-view demand (%)');title('Same trajectory: assignment helps; pose imposes a ceiling');legend({'Cyclic capped','Nearest-k','Feasible repair','Uncapped pose ceiling'},'Location','southeast');
nexttile;yyaxis left;plot(r.time,r.defect,'LineWidth',1.6);ylabel('Normalized shift commutator');yyaxis right;stairs(r.time,r.rank,'LineWidth',1.4);ylim([0 7]);ylabel('Measured aggregated rank');grid on;xlabel('Motion time (s)');title('Repaired incidence is generally noncirculant; reference gcd=2');
nexttile;ownerMap(r,r.cyclicMasks,cols);title('Capacity-admitted cyclic ownership, t=30 s');
nexttile;ownerMap(r,r.repairMasks,cols);title('Feasible repaired ownership, identical physical state');
sgtitle({'Assignment diagnosis on the PRESERVED continuous-domain trajectory: N=6, k=2','Time means: cyclic 12.44%, nearest-k 13.09%, repair / pose ceiling 25.13%; ownership colors blend overlapping IDs'},'FontWeight','bold');exportgraphics(f,fullfile(out,'E01_same_trajectory_diagnosis.png'),'Resolution',150);close(f);
f=figure('Color','w','Position',[20 20 1630 1220]);tiledlayout(3,2,'Padding','compact','TileSpacing','compact');
keys={'completion','H','speed','bytes'};titles={'Finite-job completion: six consecutive delivered reports','Common full-map nearest-k distance cost','Actual integrated chassis speed','Actual routed requests, bids, leases and task evidence'};yl={'Confirmed weighted demand (%)','H (m^2)','Speed RMS (m/s)','Cumulative byte-hops / 10^6'};
for h=1:4,nexttile;hold on;for i=1:4,p=d.primary(i);v=p.(keys{h});if h==1,v=100*v;elseif h==4,v=v/1e6;end;plot(p.time,v,'Color',method(i,:),'LineWidth',1.6);end;grid on;xlabel('Motion time (s)');ylabel(yl{h});title(titles{h});if h==1,ylim([0 105]);legend(names,'Location','southeast');end;end
nexttile;hold on;for i=1:4,p=d.primary(i);plot(p.time,p.load,'Color',method(i,:),'LineWidth',1.5);end;plot(d.primary(1).time,d.primary(1).reference,'k--');grid on;xlabel('Motion time (s)');ylabel('Relative active assigned-load RMS');title('Solid: admitted work; dashed: cyclic planned reference');
nexttile;b=bar(100*d.completion,'grouped');for i=1:4,b(i).FaceColor=method(i,:);end;grid on;ylim([0 105]);ylabel('Completed demand (%)');xticks(1:9);xticklabels({'seed2718','seed42','seed19','N5 k2','N6 k3','N7 -> 6','18k budget','disconnected','k1 infeasible'});xtickangle(28);title('Counterexamples retained: repair is not a universal winner');
sgtitle({'Matched actual 20-DoF EL fleets: finite 3D inspection, capacity, FOV, occlusion and resource booking','36 trials / 9 scenarios; completion is NOT the instantaneous metric above; motion and allocation stacks are explicit'},'FontWeight','bold');exportgraphics(f,fullfile(out,'E02_executed_missions.png'),'Resolution',150);close(f);
f=figure('Color','w','Position',[20 20 1550 1040]);tiledlayout(2,3,'Padding','compact','TileSpacing','compact');t=d.transport;
nexttile;hold on;for i=1:3,p=t(i).tray;plot3(p(:,1),p(:,2),p(:,3),'Color',method(i,:),'LineWidth',1.8);end;grid on;view(35,24);xlabel('World x (m)');ylabel('World y (m)');zlabel('Tray z (m)');title('Actual free-object trajectory');legend({'Dual arm','Left only: failed','No grasp: failed'},'Location','best');
nexttile;hold on;for i=1:3,plot(t(i).time,t(i).tray(:,3),'Color',method(i,:),'LineWidth',1.6);end;grid on;xlabel('Physical time (s)');ylabel('Tray height (m)');title('Lift, translate, lower, support and release');
nexttile;plot(t(1).time,[t(1).leftFz t(1).rightFz],'LineWidth',1.6);hold on;yline(9.81,'k--');grid on;xlabel('Physical time (s)');ylabel('Actual force on tray (N)');title('2 kg load: measured hand forces, not substituted m g');legend({'Left F_z','Right F_z','m g / 2'},'Location','best');
nexttile;hold on;for i=1:5,plot(t(i).time,t(i).xy,'LineWidth',1.5);end;grid on;xlabel('Physical time (s)');ylabel('Horizontal placement error (m)');title('Dual / heavy / long succeed; counterchecks remain failed');legend({'Dual','Left only','None','3 kg','1.5 m'},'Location','northeast');
nexttile;hold on;for i=1:3,plot(t(i).time,1e3*t(i).contact,'Color',method(i,:),'LineWidth',1.6);end;yline(-10,'k--');grid on;xlabel('Physical time (s)');ylabel('Recorded minimum contact distance (mm)');title('No-grasp failure exceeds accepted penetration bound');
nexttile;hold on;for i=[1 4 5],plot(t(i).time,1e6*t(i).grasp,'LineWidth',1.5);end;grid on;xlabel('Physical time (s)');ylabel('Max grasp-anchor mismatch (micrometers)');title('Finite numerical constraint residuals are reported');legend({'2 kg / 1 m','3 kg / 1 m','2 kg / 1.5 m'},'Location','best');
sgtitle({'One TIAGo Pro, two ideal fixed grasps, one FREE tray: actual MuJoCo dynamics','Pre-grasp fixture, planar support, compliant contacts; no pickup perception, finger slip or hardware validation'},'FontWeight','bold');exportgraphics(f,fullfile(out,'E03_bimanual_transport.png'),'Resolution',150);close(f);
end
function ownerMap(r,masks,cols)
hold on;colors=repmat([.88 .90 .92],size(r.samples,1),1);for j=1:numel(masks),ids=find(bitget(uint16(masks(j)),1:6));if ~isempty(ids),colors(j,:)=.65*mean(cols(ids,:),1)+.35;end;end;scatter(r.samples(:,1)*10,r.samples(:,2)*10,6,colors,'filled');
a=linspace(0,2*pi,200);plot(10*cos(a),10*sin(a),'Color',[.3 .4 .45]);for j=1:numel(r.obstacles),o=r.obstacles(j);fill(10*(o.x+o.r*cos(a)),10*(o.y+o.r*sin(a)),[1 1 1],'EdgeColor',[.3 .4 .45]);end
paths=r.paths;for j=1:6,if iscell(paths),p=paths{j};else,p=squeeze(paths(j,:,:));end;plot(10*p(:,1),10*p(:,2),'Color',cols(j,:),'LineWidth',1.6);plot(10*p(end,1),10*p(end,2),'o','MarkerFaceColor',cols(j,:),'MarkerEdgeColor','w');text(10*p(end,1)+.2,10*p(end,2),num2str(j),'FontSize',10);end;axis equal;axis([-10 10 -10 10]);xlabel('World x (m)');ylabel('World y (m)');grid on;
end
